","coach sightline and stop signal"],"changeRule":"Changing approach or exit distance, entry speed, turn foot, pivot strategy, marker, surface, timing, cue, intent, dose, or symptoms requires revalidation."},"population":{"exerciseCardDoesNotClassifyParticipants":true,"readinessIsWorkoutInput":true,"selectionPrerequisites":["pain-free linear acceleration and progressive deceleration","owns lower-speed planned 180-degree turns on both plant sides","safe lane and turn-zone setup","session sprint, braking, change-of-direction, and technical-fatigue budgets fit"],"excludeOrEscalate":["pain, guarding, slip, unsafe lane, repeated line overrun, collapse, balance loss, or communication conflict","new neurologic, circulation, breathing, chest, balance, or coordination concern","participant requests stop"],"notEstablishedByEvidence":["universal approach distance, pivot strategy, dose, recovery, testing norm, performance outcome, readiness threshold, or clinical clearance"]},"provenance":{"legacySources":[160,285],"identityAuthority":"Source 160 plus the focused 180-degree transitions packet: one planned approach, brake, turn, and reacceleration is the stable identity; Modified/Traditional 505 are controlled contexts and reactive or multi-turn routes are distinct.","canonicalAuthoredFromResearch":true,"primaryIdentitySource":"https://pubmed.ncbi.nlm.nih.gov/32287181/","primaryIdentitySourceStatus":"candidate_research_evidence_unreviewed","externalPlaybackVerificationPerformed":false,"oEmbedMetadataChecked":false,"humanReviewRequired":true,"approvalsCreated":false,"publicationQuarantined":true},"anatomy":{"primaryMuscles":["quadriceps","gluteal_complex","hamstring_complex","soleus","gastrocnemius"],"secondaryMuscles":["gluteus_medius","adductors","peroneal_complex","tibialis_anterior","hip_rotators","trunk_stabilizers"],"joints":["metatarsophalangeal","talocrural_ankle","knee","hip","pelvis","thoracolumbar_spine"],"jointActions":["penultimate_contact_braking","hip_knee_ankle_fo